<?php
require_once __DIR__.'/config.php'; require_auth(['admin']); require_permission('manage_backups'); $pdo=db();$tables=$pdo->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);$sql="-- AutoCare database backup\nSET FOREIGN_KEY_CHECKS=0;\n";foreach($tables as $t){$q=$pdo->query("SHOW CREATE TABLE `".str_replace('`','``',$t)."`")->fetch();$sql.="DROP TABLE IF EXISTS `{$t}`;\n".$q['Create Table'].";\n";$rows=$pdo->query("SELECT * FROM `{$t}`")->fetchAll(PDO::FETCH_ASSOC);foreach($rows as $row){$vals=[];foreach($row as $v)$vals[]=$v===null?'NULL':$pdo->quote($v);$sql.="INSERT INTO `{$t}` (`".implode('`,`',array_keys($row))."`) VALUES (".implode(',',$vals).");\n";}}$sql.="SET FOREIGN_KEY_CHECKS=1;\n";header('Content-Type: application/sql; charset=utf-8');header('Content-Disposition: attachment; filename="autocare_backup_'.date('Ymd_His').'.sql"');echo $sql;exit;